		\subfloat[A subgraph of $\mathcal{I}(\tilde{\Gamma}_{\mathcal{H}}(\mathbb{Z}_{2^2} \times \mathbb{Z}_{2^2}))$]{\begin{tikzpicture}[scale=.6, every node/.style={circle, fill=black, minimum size=4pt, inner sep=0pt}]
				
				                
				
				
				
