If $G \cong \mathbb{Z}_{3^2} \times \mathbb{Z}_3$, then Figure \ref{proj1}(a) depicts an embedding of $\mathcal{I}(\tilde{\Gamma}_\mathcal{H}(\mathbb{Z}_{3^2} \times \mathbb{Z}_3))$  on a projective plane. Hence, Theorem \ref{planar} implies that $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(G)) = 1$.\\Conversely, assume that $\tilde{g}(\mathcal{I}(\tilde{\Gamma}_\mathcal{H}(G)))$ is equal to 1. Then, by Theorem \ref{planar}, $G$ is not isomorphic to one of $\mathbb{Z}_{p_1} \times \mathbb{Z}_{p_1}$, $\mathbb{Z}_{2^\alpha} \times \mathbb{Z}_2$ or $\mathbb{Z}_2 \times \mathbb{Z}_2 \times \mathbb{Z}_{p_1^\beta}$ with $\beta =1,2$. By Lemma \ref{injgenus}, we have, if $K \leq G$ and $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(K)) > 1$, then $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(G)) > 1$. Let $K \cong \mathbb{Z}_{p_1^{\alpha_1}} \times \mathbb{Z}_{p_2^{\alpha_2}} \times \mathbb{Z}_{p_3^{\alpha_3}} \times \cdots \times \mathbb{Z}_{p_n^{\alpha_n}}\leq G$, where $p_i'$s are prime numbers and $\alpha_i'$s are non-negative integers. We consider different possibilities of $K$ with $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(K)) > 1$ case by case.\\
	 	\textbf{Case 1.} All $p_i's$ are distinct\\
	 \textbf{Case 1.1.}  If $K \cong \mathbb{Z}_{p_1^{\alpha_1}} \times \mathbb{Z}_{p_2^{\alpha_2}}$, with either $\alpha_1 \geq 5, \alpha_2 = 3$ or $\alpha_1 \geq 4, \alpha_2 = 4$, then, by Theorem \ref{projcyclic},  $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(K)) > 1$.\\ 
	 \textbf{Case 1.2.} If $K \cong \mathbb{Z}_{p_1^{\alpha_1}} \times \mathbb{Z}_{p_2} \times \mathbb{Z}_{p_3}$ with $\alpha_1 \geq 5$ or $K \cong \mathbb{Z}_{p_1^2} \times \mathbb{Z}_{p_2^2} \times \mathbb{Z}_{p_3}$, then, by Theorem \ref{projcyclic},  $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(K)) > 1$.\\
	 	\textbf{Case 1.3.} If $\omega(n) \geq 4$, then, by Theorem \ref{projcyclic}, $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(K)) > 1$.\\
	 		\textbf{Case 2.} Two $p_i's$ are same\\
	 	\textbf{Case 2.1.}  If $K \cong \mathbb{Z}_{p_1^{\alpha_1}} \times \mathbb{Z}_{p_1^{\alpha_2}}$, then consider the following cases:\\	\textbf{Case 2.1.1.} If either $p_1=2$ or $p_1 =3$ and $\alpha_1, \alpha_2 \geq 2$, then $ \tilde{\Gamma}_\mathcal{H}(\mathbb{Z}_{2^2} \times \mathbb{Z}_{2^2})$ is a subhypergraph of $\tilde{\Gamma}_\mathcal{H}(K)$ and Figure \ref{proj1}(b) depicts a drawing of a subgraph of $\mathcal{I}(\tilde{\Gamma}_\mathcal{H}(\mathbb{Z}_{2^2} \times \mathbb{Z}_{2^2}))$ on a projective plane. Clearly, it is not embeddable on a projective plane and hence, by Theorem \ref{incidencegraph2},  $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(G)) > 1$.\\
	 			\textbf{Case 2.1.2.} If $p_1 \geq 5$, then $ \mathbb{Z}_{p_1^2} \times \mathbb{Z}_{p_1}$, where $p_1 \geq 5$ is a prime, is a subgroup of $K$. Consider the following hyperedges of $ \mathbb{Z}_{p_1^2} \times \mathbb{Z}_{p_1}$: $e_1=\{<(0,1)>,<(p,1)>,<(p,2)>,<(p,0)>\}, e_2=\{<(0,1)>,<(p,1)>,<(p,2)>,<(1,0)>\}, e_3=\{<(0,1)>,<(p,1)>,<(p,2)>,<(1,1)>\}, e_4=\{<(0,1)>,<(p,1)>,<(p,2)>,<(1,2)>\}, e_5=\{<(0,1)>,<(p,1)>,<(p,2)>,<(1,3)>\}$ and  $e_6=\{<(0,1)>,<(p,1)>,<(p,2)>,<(1,4)>\}$. Hence,  $\mathcal{I}(\tilde{\Gamma}_\mathcal{H}(K))$ contains $K_{3,5}$ and consequently, $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(G)) > 1$.\\
	 			\textbf{Case 2.2.}  If $K \cong \mathbb{Z}_{p_1} \times \mathbb{Z}_{p_1} \times \mathbb{Z}_{p_2^\alpha}$, then consider the following cases:\\
	 			\textbf{Case 2.2.1.} If $p_1=2$ and $\alpha \geq 3$, then $\mathbb{Z}_2 \times \mathbb{Z}_2 \times \mathbb{Z}_{p_2^3}$ is a subgroup of $K$.  Figure \ref{proj1}(c) depicts a drawing of $\mathcal{I}(\tilde{\Gamma}_\mathcal{H}(\mathbb{Z}_{2} \times \mathbb{Z}_2 \times \mathbb{Z}_{p_2^3}))$ on a projective plane, where $H_1=<(1,0,0)>, H_2=<(0,1,0)>, H_3=<(1,1,0)>, H=\mathbb{Z}_2 \times \mathbb{Z}_2 \times \{0\}, K_1=<(0,0,p_2^2)>, K_2=<(0,0,p_2)>$ and $K_3=<(0,0,1)>$. Clearly, it is not embeddable on a projective plane and hence, by Theorem \ref{incidencegraph2}, $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(K)) > 1$.\\
