	 			\textbf{Case 2.2.2.} If $p_1 \geq 3$, then $\mathbb{Z}_{p_1} \times \mathbb{Z}_{p_1} \times \mathbb{Z}_{p_2}$ is a subgroup of $K$. Figure \ref{proj2}(a) depicts a drawing of $\mathcal{I}(\tilde{\Gamma}_\mathcal{H}(\mathbb{Z}_{p_1} \times \mathbb{Z}_{p_1} \times \mathbb{Z}_{p_2}))$ on a projective plane, where $H_1 =<(0,1,0)>, H_2=<(1,0,0)>, H_3=<(1,1,0)>, H=\mathbb{Z}_{p_1} \times \mathbb{Z}_{p_1} \times \{0\}, H'=\{0\} \times \{0\} \times \mathbb{Z}_{p_2}$. Clearly, it is not embeddable on a projective plane and hence, $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(K)) > 1$.\\
	 				\textbf{Case 2.3.} If $K \cong \mathbb{Z}_{p_1} \times \mathbb{Z}_{p_1} \times \mathbb{Z}_{p_2} \times \mathbb{Z}_{p_3}$, then  Figure \ref{proj2}(b) depicts a drawing of subgraph of  $\mathcal{I}(\tilde{\Gamma}_\mathcal{H}(\mathbb{Z}_{p_1} \times \mathbb{Z}_{p_1} \times \mathbb{Z}_{p_2})$ on a projective plane. Clearly, it is not embeddable on a projective plane and hence, by Theorem \ref{incidencegraph2},  $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(K)) > 1$.\\
	 \textbf{Case 3}  Three $p_i'$s are same\\
	 \textbf{Case 3.1.} If $ K \cong \mathbb{Z}_{p_1^{\alpha_1}} \times \mathbb{Z}_{p_1^{\alpha_2}} \times \mathbb{Z}_{p_1^{\alpha_3}}$, then $\tilde{\Gamma}_\mathcal{H}(\mathbb{Z}_2 \times \mathbb{Z}_2 \times \mathbb{Z}_2)$ is a subhypergraph of $\tilde{\Gamma}_\mathcal{H}(K)$. Figure \ref{proj2}(c) depicts a drawing of $\mathcal{I}(\tilde{\Gamma}_\mathcal{H}(\mathbb{Z}_{2} \times \mathbb{Z}_2 \times \mathbb{Z}_2))$ on a projective plane. Clearly, it is not embeddable on a projective plane and hence, by Theorem \ref{incidencegraph}, $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(K)) > 1$.\\
	  If $G$ is not isomorphic to $\mathbb{Z}_{p_1} \times \mathbb{Z}_{p_1}$, where $p_1$ is a prime or $ Z_{2^\alpha} \times \mathbb{Z}_2$	or  $ \mathbb{Z}_2 \times \mathbb{Z}_2 \times \mathbb{Z}_{p_2^\beta}$, where $p_2$ is prime and  $\beta =1,2$, or $ \mathbb{Z}_{3^2} \times \mathbb{Z}_3$, then $G$ contains a subgroup isomorphic to one of the above groups.  Hence, if $\tilde{g}(\tilde{\Gamma}_\mathcal{H}(G))$  is equal to 1, then $G \cong \mathbb{Z}_{3^2} \times \mathbb{Z}_3$.
